const ORDER_STATUS_DEFS=[
  {id:"PENDING",label:"Pending",legacy:["NEW","PENDING"]},
  {id:"CONFIRMED",label:"Confirmed",legacy:["CONFIRMED"]},
  {id:"DESIGNING",label:"Designing",legacy:["DESIGNING"]},
  {id:"READY",label:"Ready",legacy:["READY"]},
  {id:"PICKUP_READY",label:"Pickup Ready",legacy:["PICKUP_READY"]},
  {id:"OUT_FOR_DELIVERY",label:"Out for Delivery",legacy:["OUT_FOR_DELIVERY"]},
  {id:"DELIVERED",label:"Delivered",legacy:["DELIVERED"]},
  {id:"COMPLETED",label:"Completed",legacy:["COMPLETED"]},
  {id:"ON_HOLD",label:"On Hold",legacy:["ON_HOLD"]},
  {id:"ISSUE",label:"Issue",legacy:["ISSUE"]},
  {id:"CANCELLED",label:"Cancelled",legacy:["CANCELLED"]}
];
const ORDER_BOARD_COLUMNS=[
  {id:"PENDING",label:"Pending",statuses:["NEW","PENDING","CONFIRMED"]},
  {id:"DESIGNING",label:"Designing",statuses:["DESIGNING"]},
  {id:"READY",label:"Ready",statuses:["READY","PICKUP_READY"]},
  {id:"OUT_FOR_DELIVERY",label:"Out for Delivery",statuses:["OUT_FOR_DELIVERY"]},
  {id:"DELIVERED",label:"Delivered",statuses:["DELIVERED"]},
  {id:"COMPLETED",label:"Completed",statuses:["COMPLETED"]},
  {id:"ON_HOLD",label:"On Hold",statuses:["ON_HOLD"]},
  {id:"ISSUE",label:"Issue",statuses:["ISSUE"]},
  {id:"CANCELLED",label:"Cancelled",statuses:["CANCELLED"]}
];
const ORDER_ADVANCE_SEQUENCE=["PENDING","CONFIRMED","DESIGNING","READY","PICKUP_READY","OUT_FOR_DELIVERY","DELIVERED","COMPLETED"];
function canonicalOrderStatus(value){const raw=String(value||"NEW").toUpperCase();const def=ORDER_STATUS_DEFS.find(s=>s.legacy.includes(raw)||s.id===raw);return def?.id||"PENDING"}
function boardColumnForStatus(status){const raw=String(status||"NEW").toUpperCase();const col=ORDER_BOARD_COLUMNS.find(c=>c.statuses.includes(raw));return col?.id||"PENDING"}
function orderStatusLabel(id){return ORDER_STATUS_DEFS.find(s=>s.id===id)?.label||id}
function nextAdvanceStatus(current){const canon=canonicalOrderStatus(current);const idx=ORDER_ADVANCE_SEQUENCE.indexOf(canon);if(idx<0||idx>=ORDER_ADVANCE_SEQUENCE.length-1)return null;return ORDER_ADVANCE_SEQUENCE[idx+1]}
function normalizeOrderStatus(value){return canonicalOrderStatus(value)}
function populateOrderStatusSelect(selected){const sel=$("#orderStatusSelect");if(!sel)return;sel.innerHTML=ORDER_STATUS_DEFS.map(s=>`<option value="${s.id}">${esc(s.label)}</option>`).join("");sel.value=canonicalOrderStatus(selected||"PENDING")}
async function loadOrderStatusHistory(orderId){const box=$("#orderStatusHistory"),section=$("#orderStatusHistorySection");if(!box||!orderId){section?.setAttribute("hidden","");return}section?.removeAttribute("hidden");box.innerHTML='<p class="subtle">Loading status history…</p>';try{const {items}=await api(`orders?order_id=${encodeURIComponent(orderId)}&view=history`);box.innerHTML=items?.length?items.map(row=>{const from=row.from_status?orderStatusLabel(canonicalOrderStatus(row.from_status)):"Start";const to=orderStatusLabel(canonicalOrderStatus(row.to_status));const when=new Date(row.created_at).toLocaleString();return `<div class="status-history-row"><strong>${esc(from)} → ${esc(to)}</strong><time datetime="${esc(row.created_at)}">${esc(when)}</time></div>`}).join(""):'<p class="subtle">No status changes recorded yet.</p>'}catch{box.innerHTML='<p class="subtle">Status history will appear after the Foundation migration is applied.</p>'}}
function orderTelemetry(message,type="info"){
  const log=$("#telemetryLog");if(!log)return;
  const row=document.createElement("p");if(type!=="info")row.className=type;
  const time=document.createElement("time");time.textContent=new Date().toLocaleTimeString([],{hour:"2-digit",minute:"2-digit",second:"2-digit"});
  const text=document.createElement("span");text.textContent=message;row.append(time,text);log.prepend(row);
  while(log.children.length>40)log.lastElementChild.remove();
}
function cogsSnapshot(o){const total=Math.max(0,Number(o.total||0)),cost=Math.max(0,Number(o.estimated_cost||0));const ratio=total?cost/total:0;return {total,cost,ratio,over:cost>0&&ratio>.33}}
