function renderInventory(){
  const q=($("#inventorySearch")?.value||"").trim().toLowerCase(),color=$("#inventoryColorFilter")?.value||"",freshFilter=$("#inventoryFreshnessFilter")?.value||"";
  const rows=inventory.filter(i=>!color||(i.color||"")===color).filter(i=>!freshFilter||inventoryFreshnessBucket(i)===freshFilter).filter(i=>[i.name,i.category,i.color,i.variety,i.lot_code,i.supplier].join(" ").toLowerCase().includes(q));
  const retail=rows.reduce((sum,i)=>sum+Number(i.quantity||0)*Number(i.price||0),0);if($("#inventoryRetailValue"))$("#inventoryRetailValue").textContent=money(retail);
  const listEl=$("#inventoryList");if(listEl)listEl.classList.add("bloom-inventory-visual");
  const helpers={inventoryFreshness};
  $("#inventoryList").innerHTML=rows.length?rows.map(i=>window.BloomRC21?.inventoryCard?.(i,helpers)||(()=>{const f=inventoryFreshness(i),freshClass=f.score<=25?"danger":f.score<=55?"warn":"good";return `<article class="card inventory-card${f.useFirst?" use-first-item":""}"><div class="card-top"><div><div class="inventory-title-row"><h3>${esc(i.name)}</h3>${i.color?`<span class="color-label">${esc(i.color)}</span>`:""}${f.useFirst?'<span class="badge warn">USE FIRST</span>':""}</div><div class="meta">${esc(i.category)}${i.variety?` · ${esc(i.variety)}`:""} · ${Number(i.quantity||0)} ${esc(i.unit)}</div></div><span class="badge ${Number(i.quantity)<=Number(i.low_stock_level)?"warn":"good"}">${Number(i.quantity)<=Number(i.low_stock_level)?"LOW":"IN STOCK"}</span></div><div class="freshness-meter"><div><span>Vase-life countdown</span><b class="${freshClass}">${f.label} · Day ${f.age}</b></div><progress max="100" value="${f.score}"></progress><small>${f.score}% freshness${i.received_at||i.arrival_date?` · Received ${dateText(i.received_at||i.arrival_date)}`:""}${i.use_by?` · Use by ${dateText(i.use_by)}`:""}${i.lot_code?` · Lot ${esc(i.lot_code)}`:""}${i.supplier?` · ${esc(i.supplier)}`:""}${i.markup_multiplier?` · ${Number(i.markup_multiplier)}× markup`:""}</small></div><div class="inventory-pricing"><span>Wholesale <strong>${money(i.cost)}</strong></span><span>Retail <strong>${money(i.price)}</strong></span><span>Stock retail value <strong>${money(Number(i.quantity||0)*Number(i.price||0))}</strong></span></div><div class="card-actions"><button class="secondary" data-edit-inventory="${i.id}">Edit</button><button class="secondary" data-delete-inventory="${i.id}">Delete</button></div></article>`})()).join(""):empty("No inventory matches this view.")
}
