function loadPosCart(){try{posCart=JSON.parse(localStorage.getItem("bloom_pos_cart")||"[]");if(!Array.isArray(posCart))posCart=[]}catch{posCart=[]}try{savedQuotes=JSON.parse(localStorage.getItem("bloom_saved_quotes")||"[]");if(!Array.isArray(savedQuotes))savedQuotes=[]}catch{savedQuotes=[]}renderPosCart();renderSavedQuotes()}
function cartTotals(){const subtotal=posCart.reduce((s,x)=>s+(Number(x.price)||0)*(Number(x.quantity)||1),0),rate=Number(shopSettings?.tax_rate??6),tax=Math.round(subtotal*rate)/100,total=subtotal+tax;return{subtotal,tax,total,rate}}
function renderPosCustomerOptions(){const select=$("#posCustomerSelect");if(!select)return;const current=select.value;select.innerHTML='<option value="">Walk-in Customer</option>'+customers.map(c=>`<option value="${esc(c.id||c.name)}" data-name="${esc(c.name)}">${esc(c.name)}</option>`).join("");select.value=[...select.options].some(o=>o.value===current)?current:""}
function renderPosCart(){const box=$("#queue");if(!box)return;const {subtotal,tax,total,rate}=cartTotals();$("#cartItemCount").textContent=`${posCart.reduce((s,x)=>s+Number(x.quantity||1),0)} items`;box.innerHTML=posCart.length?`<div class="cart-table"><div class="cart-table-head"><span>Item</span><span>Qty</span><span>Price</span><span>Total</span><span></span></div>${posCart.map((x,i)=>`<div class="cart-row"><span><strong>${esc(x.name)}</strong>${x.description?`<small>${esc(x.description)}</small>`:""}</span><span class="qty-control"><button data-cart-minus="${i}">−</button><b>${Number(x.quantity)||1}</b><button data-cart-plus="${i}">+</button></span><span><input data-cart-price="${i}" type="number" min="0" step=".01" value="${Number(x.price||0).toFixed(2)}"></span><span><b>${money((Number(x.price)||0)*(Number(x.quantity)||1))}</b></span><span><button class="icon-delete" data-cart-remove="${i}" aria-label="Remove">🗑</button></span></div>`).join("")}</div>`:empty("Tap a product picture, enter the price, and it will appear here.");$("#weekSales").textContent=money(subtotal);const taxLine=$$(".checkout-lines span").find(x=>x.textContent.includes("Tax ("));if(taxLine)taxLine.innerHTML=`Tax (${rate.toFixed(1)}%) <b>${money(tax)}</b>`;$("#totalSales").textContent=money(total);const pay=$(".process-payment");if(pay){pay.disabled=!posCart.length;pay.dataset.cartCheckout="1"}}
function persistSavedQuotes(){localStorage.setItem("bloom_saved_quotes",JSON.stringify(savedQuotes));renderSavedQuotes()}
function renderSavedQuotes(){const count=$("#savedQuoteCount");if(count)count.textContent=String(savedQuotes.length);const box=$("#savedQuotesList");if(!box)return;box.innerHTML=savedQuotes.length?savedQuotes.map(q=>`<article class="saved-quote-card"><div><strong>${esc(q.name)}</strong><small>${new Date(q.createdAt).toLocaleString()} · ${q.cart.reduce((n,x)=>n+Number(x.quantity||1),0)} items · ${money(q.total)}</small></div><div><button class="primary" data-load-quote="${q.id}" type="button">Resume</button><button class="secondary" data-delete-quote="${q.id}" type="button">Delete</button></div></article>`).join(""):empty("No saved quotes on this device.")}
function saveCurrentQuote(){if(!posCart.length)return toast("Add an item before saving a quote");const customerOption=$("#posCustomerSelect")?.selectedOptions?.[0],customerName=customerOption?.dataset?.name||"Walk-in Customer",name=prompt("Quote name",`${customerName} quote`)?.trim();if(!name)return;const totals=cartTotals();savedQuotes.unshift({id:`quote-${Date.now()}`,name,createdAt:new Date().toISOString(),customerId:$("#posCustomerSelect")?.value||"",note:$("#posOrderNote")?.value||"",cart:structuredClone(posCart),total:totals.total});savedQuotes=savedQuotes.slice(0,25);persistSavedQuotes();toast("Quote saved on this register")}
function loadSavedQuote(id){const q=savedQuotes.find(x=>x.id===id);if(!q)return;posCart=structuredClone(q.cart||[]);if($("#posCustomerSelect"))$("#posCustomerSelect").value=q.customerId||"";if($("#posOrderNote"))$("#posOrderNote").value=q.note||"";savePosCart();$("#savedQuotesDialog")?.close();toast(`Loaded ${q.name}`)}
function syncLegacyPaymentFields(order){const{balance}=orderPaymentView(order||pendingPaymentOrder||{});const amt=balance>0?balance.toFixed(2):"0.00";if($("#paymentAmount"))$("#paymentAmount").value=amt;if($("#cardPaymentAmount"))$("#cardPaymentAmount").value=amt;if($("#cashPaymentAmount"))$("#cashPaymentAmount").value=amt;if($("#cashReceived"))$("#cashReceived").value=amt;if($("#checkPaymentAmount"))$("#checkPaymentAmount").value=amt;if($("#paymentDescription"))$("#paymentDescription").value=`${order?.order_number||pendingPaymentOrder?.order_number||"Florisyn order"} - ${order?.customer_name||pendingPaymentOrder?.customer_name||"Customer"}`}
function getPaymentBalance(){return orderPaymentView(pendingPaymentOrder||{}).balance}
function renderPaymentCenterShell(){const empty=$("#paymentCenterEmpty"),active=$("#paymentCenterActive");if(!pendingPaymentOrder?.id){if(empty)empty.hidden=false;if(active)active.hidden=true;renderPendingPayment();return}if(empty)empty.hidden=true;if(active)active.hidden=false;renderPaymentTopSummary();renderPendingPayment()}
function renderPaymentTopSummary(){const box=$("#paymentTopSummary");if(!box||!pendingPaymentOrder)return;const pv=orderPaymentView(pendingPaymentOrder);box.dataset.balance=String(pv.balance);box.innerHTML=`<p class="pay-customer">${esc(pendingPaymentOrder.customer_name||"Customer")}</p><p class="pay-order-meta">Order ${esc(pendingPaymentOrder.order_number||"—")}</p><div class="pay-stats"><div><span>Order total</span><strong>${money(pv.total)}</strong></div><div><span>Already paid</span><strong>${money(pv.paid)}</strong></div><div class="pay-balance-block"><span>Balance due</span><strong>${money(pv.balance)}</strong></div><div><span>Status</span><strong><span class="badge ${paymentBadgeClass(pv.status)}">${esc(pv.status)}</span></strong></div></div>`}
function renderPendingPayment(){const box=$("#pendingPaymentSummary"),full=$("#useFullBalance");if(!box)return;if(!pendingPaymentOrder){box.innerHTML="";if(full)full.disabled=true;return}const pv=orderPaymentView(pendingPaymentOrder);box.dataset.balance=String(pv.balance);box.innerHTML=`<span data-legacy-summary>${money(pv.balance)}</span>`;if(full)full.disabled=pv.balance<=0}
function hideAllPaymentFlows(){["paymentFlowCash","paymentFlowCard","paymentFlowCheck","paymentFlowSplit","paymentFlowPayLater","paymentSuccessPanel"].forEach(id=>{const el=$("#"+id);if(el)el.hidden=true});$("#paymentMethodPicker")?.removeAttribute("hidden");document.querySelector(".payment-more-methods")?.removeAttribute("hidden")}
function setPaymentCenterMode(mode){hideAllPaymentFlows();$("#splitPaymentError")&&( $("#splitPaymentError").textContent="");const picker=$("#paymentMethodPicker"),more=document.querySelector(".payment-more-methods");if(mode==="methods"){picker?.removeAttribute("hidden");more?.removeAttribute("hidden");return}picker&&(picker.hidden=true);more&&(more.hidden=true);if(mode==="cash"){const bal=getPaymentBalance();$("#cashPaymentAmount").value=bal>0?bal.toFixed(2):"0.00";$("#cashReceived").value=bal>0?bal.toFixed(2):"0.00";updateCashMath();$("#paymentFlowCash").hidden=false;$("#cashPaymentAmount")?.focus()}else if(mode==="card"){const bal=getPaymentBalance();$("#cardPaymentAmount").value=bal>0?bal.toFixed(2):"0.00";syncLegacyPaymentFields(pendingPaymentOrder);$("#paymentFlowCard").hidden=false}else if(mode==="check"){const bal=getPaymentBalance();$("#checkPaymentAmount").value=bal>0?bal.toFixed(2):"0.00";const btn=$("#completeCheckPayment");if(btn)btn.dataset.moreMethod="Check";const h2=$("#paymentFlowCheck")?.querySelector("h2");if(h2)h2.textContent="Check payment";$("#paymentFlowCheck").hidden=false}else if(mode==="split"){ensureSplitSession();if(!$("#splitPaymentRows")?.querySelector(".split-part-row"))renderSplitPaymentRows(defaultSplitRowsForRemaining());else updateSplitTotals();$("#paymentFlowSplit").hidden=false}else if(mode==="pay-later"){$("#paymentFlowPayLater").hidden=false}else if(mode==="success"){$("#paymentSuccessPanel").hidden=false}}
function updateCashMath(){const pay=Number($("#cashPaymentAmount")?.value||0),received=Number($("#cashReceived")?.value||0),balance=getPaymentBalance();const change=Math.max(0,Math.round((received-pay)*100)/100);const after=Math.max(0,Math.round((balance-pay)*100)/100);if($("#cashChangeDue"))$("#cashChangeDue").textContent=money(change);if($("#cashBalanceAfter"))$("#cashBalanceAfter").textContent=money(after);$("#paymentAmount").value=pay>0?pay.toFixed(2):"0.00"}
function returnFromPaymentCenter(){clearSplitSession();const id=paymentReturnOrderId||pendingPaymentOrder?.id;paymentReturnOrderId=null;showPage("ordersPage");if(id){const card=document.querySelector(`[data-order-card="${id}"]`);card?.scrollIntoView({behavior:"smooth",block:"nearest"})}}
function cancelPaymentCenter(){clearSplitSession();setPaymentCenterMode("methods");if($("#paymentStatus"))$("#paymentStatus").textContent=""}
function loadSplitSessionFromStorage(){try{splitPaymentSession=JSON.parse(sessionStorage.getItem("bloom_split_payment_session")||"null")}catch{splitPaymentSession=null}return splitPaymentSession}
function saveSplitSession(){if(splitPaymentSession)sessionStorage.setItem("bloom_split_payment_session",JSON.stringify(splitPaymentSession));else sessionStorage.removeItem("bloom_split_payment_session")}
function clearSplitSession(){splitPaymentSession=null;sessionStorage.removeItem("bloom_split_payment_session");sessionStorage.removeItem("bloom_split_stripe_return")}
function ensureSplitSession(){loadSplitSessionFromStorage();if(!pendingPaymentOrder?.id){splitPaymentSession=null;saveSplitSession();return null}if(!splitPaymentSession||splitPaymentSession.orderId!==pendingPaymentOrder.id){splitPaymentSession={orderId:pendingPaymentOrder.id,batchId:(crypto.randomUUID?crypto.randomUUID():`split-${Date.now()}`),partSeq:0};saveSplitSession()}return splitPaymentSession}
function defaultSplitRowsForRemaining(){const balance=getPaymentBalance();const half=balance>0?Math.round(balance*50)/100:0;return splitPaymentSession?.partSeq>0||balance<=0?[{method:"Cash",amount:balance,note:""}]:[{method:"Cash",amount:half,note:""},{method:"Card",amount:Math.max(0,Math.round((balance-half)*100)/100),note:""}]}
function continueSplitWorkflow(order,statusMessage){ensureSplitSession();renderSplitWorkflowStep(order,statusMessage)}
function renderSplitWorkflowStep(order,statusMessage){if(order)setPendingPaymentOrder(order);renderPaymentCenterShell();setPaymentCenterMode("split");renderSplitPaymentRows(defaultSplitRowsForRemaining());if($("#paymentStatus")&&statusMessage)$("#paymentStatus").textContent=statusMessage;refreshPaymentHistory()}
async function completeSplitWorkflow(order){clearSplitSession();if(order)setPendingPaymentOrder(order);await refreshPaymentHistory();showPaymentSuccessPanel({detail:`Split payment complete. Balance ${money(orderPaymentView(order||pendingPaymentOrder).balance)}.<br>Print receipt to show every tender.`,order:order||pendingPaymentOrder});toast("Split payment complete")}
async function handleSplitPaymentContinuation(result,deferred=[]){const order=result.order||pendingPaymentOrder;if(order)setPendingPaymentOrder(order);await Promise.all([loadOrders(),loadDashboard(),loadInvoices()]);const balance=orderPaymentView(order).balance;if(deferred?.length){const amt=Math.min(Number(deferred[0].amount||0),balance);if(amt>=0.5){toast(`Opening Stripe for ${money(amt)}…`);await startSplitStripeCheckout(amt);return}}if(balance>0.005){continueSplitWorkflow(order,`Remaining balance ${money(balance)}. Add the next tender and tap Complete Split Payment.`);toast(`Tender recorded — ${money(balance)} still due`);return}await completeSplitWorkflow(order)}
async function startSplitStripeCheckout(amount){if(!pendingPaymentOrder?.id)throw new Error("Choose an order first.");ensureSplitSession();sessionStorage.setItem("bloom_split_stripe_return","1");saveSplitSession();const description=$("#paymentDescription")?.value?.trim()||`${pendingPaymentOrder.order_number||"Order"} split card payment`;setPaymentProcessing(true);try{const d=await api("create-checkout",{method:"POST",body:JSON.stringify({amount,description,order_id:pendingPaymentOrder.id,order_number:pendingPaymentOrder.order_number||""})});if(!d.url)throw new Error("Stripe did not return a checkout link.");location.assign(d.url)}catch(e){sessionStorage.removeItem("bloom_split_stripe_return");setPaymentProcessing(false);throw e}}
async function handleSplitAfterStripe(order){loadSplitSessionFromStorage();await Promise.all([loadOrders(),loadDashboard(),loadInvoices()]);await handleSplitPaymentContinuation({order},[])}
function showPaymentSuccessPanel({headline,detail,order}){if(order)setPendingPaymentOrder(order);renderPaymentCenterShell();if($("#paymentSuccessDetail"))$("#paymentSuccessDetail").innerHTML=detail||headline||"Payment recorded.";setPaymentCenterMode("success");refreshPaymentHistory()}
async function refreshPaymentHistory(){const body=$("#paymentHistoryBody");if(!body||!pendingPaymentOrder?.id){if(body)body.innerHTML='<p class="subtle">Select an order to view payment history.</p>';return}body.innerHTML='<p class="subtle">Loading…</p>';try{const items=(await api(`payments?order_id=${encodeURIComponent(pendingPaymentOrder.id)}`)).items||[];if(!items.length){body.innerHTML='<p class="subtle">No payments recorded yet.</p>';return}body.innerHTML=`<table class="payment-history-table"><thead><tr><th>Date</th><th>Method</th><th>Amount</th><th>Status</th></tr></thead><tbody>${items.map(p=>{const label=p.metadata?.tender_label||p.method;const dt=p.received_at?new Date(p.received_at).toLocaleString():"—";return `<tr><td>${esc(dt)}</td><td>${esc(label)}</td><td>${money(p.amount)}</td><td>${esc(p.status||"SUCCEEDED")}</td></tr>`}).join("")}</tbody></table>`}catch(e){body.innerHTML=`<p class="subtle">${esc(e.message||"Could not load history.")}</p>`}}
function setPaymentProcessing(on){paymentCenterProcessing=on;["completeCashPayment","completeCheckPayment","completeSplitPayment","checkout","confirmPayLater"].forEach(id=>{const b=$("#"+id);if(b)b.disabled=on})}
async function postManualPayment(method,amount,note){if(paymentCenterProcessing)return;if(!pendingPaymentOrder?.id)throw new Error("Choose an order before recording this payment.");if(amount<=0)throw new Error("Enter a valid payment amount.");setPaymentProcessing(true);if($("#paymentStatus"))$("#paymentStatus").textContent=`Recording ${method} payment…`;try{const key=(crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random()}`);const payload={order_id:pendingPaymentOrder.id,amount,method,idempotency_key:key};if(note)payload.note=note;const result=await api("payments",{method:"POST",body:JSON.stringify(payload)});return result.order||result}finally{setPaymentProcessing(false)}}
async function recordLocalPayment(method){try{const amount=Number($("#paymentAmount")?.value||0);const order=await postManualPayment(method,amount);setPendingPaymentOrder(order);const balance=Number(order?.balance_due??0);if($("#paymentStatus"))$("#paymentStatus").textContent=`${method} payment recorded. Remaining balance: ${money(balance)}.`;toast(`${method} payment recorded`);await Promise.all([loadOrders(),loadDashboard(),loadInvoices()]);return order}catch(e){const msg=e?.message||"Payment could not be recorded.";toast(msg);if($("#paymentStatus"))$("#paymentStatus").textContent=msg;throw e}}
const SPLIT_METHODS=["Cash","Check","Card","Other"];
async function submitSplitPayment(){if(paymentCenterProcessing||!pendingPaymentOrder?.id)return toast("Choose an order first");const parts=readSplitRows().filter(p=>Number(p.amount)>0);if(!parts.length)return toast("Add at least one payment part");const session=ensureSplitSession();const batchId=session.batchId;let seq=session.partSeq||0;setPaymentProcessing(true);try{$("#splitPaymentError").textContent="";if($("#paymentStatus"))$("#paymentStatus").textContent="Applying split payment…";const result=await api("payments",{method:"POST",body:JSON.stringify({action:"split",order_id:pendingPaymentOrder.id,split_batch_id:batchId,parts:parts.map(p=>{const key=`${batchId}:part:${seq++}`;return{...p,idempotency_key:key}})})});session.partSeq=seq;saveSplitSession();await handleSplitPaymentContinuation(result,result.deferred_card_parts||[])}catch(err){const msg=err?.message||"Split payment failed";$("#splitPaymentError").textContent=msg;if($("#paymentStatus"))$("#paymentStatus").textContent=msg;toast(msg)}finally{setPaymentProcessing(false)}}
function renderSplitPaymentRows(rows){const host=$("#splitPaymentRows");if(!host)return;host.innerHTML=rows.map((r,i)=>`<li class="split-part-row" data-split-index="${i}"><span class="part-num">${i+1}.</span><select data-split-method aria-label="Payment method ${i+1}">${SPLIT_METHODS.map(m=>`<option ${m===r.method?"selected":""}>${m}</option>`).join("")}</select><input type="number" min="0.01" step="0.01" data-split-amount value="${Number(r.amount||0).toFixed(2)}" aria-label="Amount ${i+1}"><input data-split-note value="${esc(r.note||"")}" placeholder="Note" aria-label="Note ${i+1}">${rows.length>1?`<button type="button" class="secondary" data-split-remove="${i}">Remove</button>`:""}</li>`).join("");updateSplitTotals()}
function readSplitRows(){return [...($("#splitPaymentRows")?.querySelectorAll(".split-part-row")||[])].map(row=>({amount:Number(row.querySelector("[data-split-amount]")?.value||0),method:row.querySelector("[data-split-method]")?.value||"Cash",note:row.querySelector("[data-split-note]")?.value||""}))}
function updateSplitTotals(){const balance=Number($("#paymentTopSummary")?.dataset.balance||getPaymentBalance());const rows=readSplitRows();const splitTotal=Math.round(rows.reduce((s,r)=>s+Number(r.amount||0),0)*100)/100;const manualTotal=Math.round(rows.filter(r=>r.method!=="Card").reduce((s,r)=>s+Number(r.amount||0),0)*100)/100;const cardTotal=Math.round(rows.filter(r=>r.method==="Card").reduce((s,r)=>s+Number(r.amount||0),0)*100)/100;if($("#splitTotalLive"))$("#splitTotalLive").textContent=money(splitTotal);if($("#splitRemainingLive"))$("#splitRemainingLive").textContent=money(Math.max(0,balance-manualTotal));const err=$("#splitPaymentError");if(err)err.textContent=splitTotal>balance+0.005?`Split total ${money(splitTotal)} exceeds balance ${money(balance)}.`:"";const notice=$("#splitCardNotice");if(notice){if(cardTotal>0){notice.hidden=false;notice.textContent=`Card total ${money(cardTotal)} opens Stripe for that amount after cash/check/other parts post.`}else notice.hidden=true}}
function setPendingPaymentOrder(order){pendingPaymentOrder=order||null;if(order)localStorage.setItem("bloom_pending_payment_order",JSON.stringify(order));else{localStorage.removeItem("bloom_pending_payment_order");clearSplitSession()}renderPaymentCenterShell()}
async function checkoutPosCart(){if(!posCart.length)return toast("Add an item first");const customerSelect=$("#posCustomerSelect"),option=customerSelect.selectedOptions[0],customerName=option?.dataset.name||"Walk-in Customer",note=$("#posOrderNote")?.value||"",{subtotal,tax,total,rate}=cartTotals();const description=posCart.map(x=>`${x.quantity} × ${x.name}${x.description?` (${x.description})`:""}`).join("; ");try{const result=await api("orders",{method:"POST",body:JSON.stringify({customer_name:customerName,customer_phone:"",customer_type:"PERSONAL",payment_required:"YES",recipient_name:customerName,occasion:"",order_source:"Walk-in",arrangement_description:description,notes:note,fulfillment:"PICKUP",delivery_date:new Date().toISOString().slice(0,10),subtotal,labor_charge:0,delivery_fee:0,discount:0,tax_rate:rate,tax,estimated_cost:0,total_preview:total})});const order=result.item||{};posCart=[];savePosCart();if($("#posOrderNote"))$("#posOrderNote").value="";toast("Order created — choose a payment method");await openPaymentCenterForOrder(order);loadOrders();loadDashboard()}catch(e){toast(e.message)}}
