let wakeRecognition=null,wakeEnabled=false,wakeRestartTimer=null,wakeBusy=false,wakeAwaitingPersona=null,wakeIgnoreUntil=0;
function wakeUi(message,state="") {const box=$("#assistantWakeToggle")?.parentElement,status=$("#assistantWakeStatus"),button=$("#assistantWakeToggle");if(status)status.textContent=message;if(box){box.classList.toggle("active",wakeEnabled);box.classList.toggle("listening",state==="listening");box.classList.toggle("error",state==="error")}if(button)button.textContent=wakeEnabled?'⏹ Turn off “Hey Lily / Hey Rose”':'🎙️ Turn on “Hey Lily / Hey Rose”'}
function stopWakeListening(){wakeEnabled=false;clearTimeout(wakeRestartTimer);wakeRestartTimer=null;try{wakeRecognition?.stop()}catch{}wakeRecognition=null;wakeBusy=false;wakeAwaitingPersona=null;wakeUi("Hands-free listening is off.")}
function acknowledgeWake(persona){const response=persona==="Rose"?"I’m here, sweetheart. Tell me what needs your attention.":"Absolutely—I'm right here with you, and I’m ready to help.";const out=$("#assistantAnswer");if(out)out.textContent=`${persona}: ${response}`;speakAssistant(response,persona,true)}
function handleWakeTranscript(transcript){if(Date.now()<wakeIgnoreUntil||wakeBusy)return;const clean=(transcript||"").trim();const match=clean.match(/(?:hey\s+)?(lily|rose)\b[\s,.:;-]*(.*)$/i);if(!match){if(wakeAwaitingPersona&&clean){const persona=wakeAwaitingPersona;wakeAwaitingPersona=null;const input=$("#assistantPrompt");if(input)input.value=clean;wakeBusy=true;runAssistant(clean,persona).finally(()=>{wakeBusy=false})}return}const persona=match[1].toLowerCase()==="rose"?"Rose":"Lily";const command=(match[2]||"").trim();assistantPersona=persona;setAssistantPersona(persona);wakeIgnoreUntil=Date.now()+1200;acknowledgeWake(persona);if(command){wakeAwaitingPersona=null;const input=$("#assistantPrompt");if(input)input.value=command;wakeBusy=true;setTimeout(()=>runAssistant(command,persona).finally(()=>{wakeBusy=false}),650)}else{wakeAwaitingPersona=persona;const input=$("#assistantPrompt");if(input)input.value="";wakeUi(`${persona} heard you. Say your question now…`,"listening")}}
function startWakeListening(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){wakeUi("Hands-free wake phrases are not supported in this browser. Use Chrome or Edge.","error");return}wakeEnabled=true;wakeRecognition=new SR();wakeRecognition.lang="en-US";wakeRecognition.continuous=true;wakeRecognition.interimResults=false;wakeRecognition.maxAlternatives=1;wakeRecognition.onstart=()=>wakeUi('Listening for “Hey Lily” or “Hey Rose”…',"listening");wakeRecognition.onresult=e=>{for(let i=e.resultIndex;i<e.results.length;i++){if(e.results[i].isFinal)handleWakeTranscript(e.results[i][0].transcript)}};wakeRecognition.onerror=e=>{if(e.error==="not-allowed"||e.error==="service-not-allowed"){wakeEnabled=false;wakeUi("Microphone permission was blocked. Allow microphone access, then turn this on again.","error")}else if(e.error!=="no-speech"&&e.error!=="aborted")wakeUi(`Voice listening paused: ${e.error}. Retrying…`,"error")};wakeRecognition.onend=()=>{wakeRecognition=null;if(wakeEnabled){clearTimeout(wakeRestartTimer);wakeRestartTimer=setTimeout(()=>{if(wakeEnabled&&!wakeBusy)startWakeListening()},500)}};try{wakeRecognition.start()}catch(e){wakeUi("Could not start microphone listening. Refresh and try again.","error")}}
$("#assistantWakeToggle")?.addEventListener("click",()=>wakeEnabled?stopWakeListening():startWakeListening());
document.addEventListener("visibilitychange",()=>{if(document.hidden&&wakeRecognition){try{wakeRecognition.stop()}catch{}}else if(!document.hidden&&wakeEnabled&&!wakeRecognition)startWakeListening()});
